"""Pydantic validation schemas for structured AI intelligence and content outputs."""

from typing import Any, Optional
from pydantic import BaseModel, Field


class ImportantFileInsight(BaseModel):
    """Insight into a key file identified in the repository tree."""
    path: str = Field(description="Relative path of the file in the repository")
    purpose: str = Field(description="Concise description of the file's architectural purpose")


class StructuredAnalysis(BaseModel):
    """Complete, evidence-based technical intelligence dossier generated by AI."""

    simple_explanation: str = Field(
        description="Clear, accessible explanation of the project suitable for non-experts."
    )
    technical_architecture: str = Field(
        description="Detailed explanation of the internal system design, pipelines, and patterns."
    )
    identified_technologies: list[str] = Field(
        default_factory=list,
        description="Explicit list of detected languages, frameworks, libraries, and databases."
    )
    important_files: list[ImportantFileInsight] = Field(
        default_factory=list,
        description="Key architectural source files and their identified responsibilities."
    )
    key_functions: list[str] = Field(
        default_factory=list,
        description="Main workflows, public APIs, or functional modules."
    )
    practical_applications: list[str] = Field(
        default_factory=list,
        description="Practical real-world use cases and deployment scenarios."
    )
    implementation_details: list[str] = Field(
        default_factory=list,
        description="Interesting or notable implementation patterns, algorithms, or optimizations."
    )
    limitations: list[str] = Field(
        default_factory=list,
        description="Observed architectural constraints, unhandled edge cases, or missing features."
    )
    learning_opportunities: list[str] = Field(
        default_factory=list,
        description="Key engineering takeaways and educational concepts demonstrated."
    )
    potential_research_topics: list[str] = Field(
        default_factory=list,
        description="Future research ideas, technical deep dive questions, or benchmark proposals."
    )
    evidence_sources: list[str] = Field(
        default_factory=list,
        description="README sections or source files cited as evidence for these claims."
    )

    def to_dict(self) -> dict[str, Any]:
        """Convert to dictionary representation for database storage."""
        return self.model_dump()


class ContentDraftSchema(BaseModel):
    """Structured educational content draft synthesized for multi-platform distribution."""

    platform: str = Field(description="Target platform (youtube, shorts, facebook, instagram, telegram, blog)")
    content_type: str = Field(description="Format type (script, post, article, tutorial, carousel)")
    language: str = Field(description="Content language (en, bn, banglish)")
    tone: str = Field(description="Tone of voice")
    audience_level: str = Field(description="Beginner, Intermediate, or Advanced")
    
    title: str = Field(description="Engaging, accurate title")
    hook: str = Field(description="Compelling opening hook or introductory line")
    body: str = Field(description="Complete main script, article, post body, or tutorial text")
    practical_explanation: str = Field(description="Hands-on explanation of how it works and what it does")
    visual_demo_suggestions: list[str] = Field(
        default_factory=list,
        description="Visual demo suggestions, thumbnail concepts, or B-roll ideas"
    )
    cta: str = Field(description="Call to action directing users to explore or comment")
    hashtags: list[str] = Field(
        default_factory=list,
        description="Relevant hashtags for distribution"
    )
    source_url: str = Field(description="Original GitHub repository URL")

    def to_dict(self) -> dict[str, Any]:
        return self.model_dump()

    def to_markdown(self) -> str:
        """Format the draft as clean markdown for export and download."""
        demo_lines = "\n".join([f"- {d}" for d in self.visual_demo_suggestions])
        tags_line = " ".join([f"#{t.lstrip('#')}" for t in self.hashtags])
        return f"""# {self.title}

> **Platform**: {self.platform.upper()} | **Format**: {self.content_type.title()} | **Language**: {self.language.upper()} | **Audience**: {self.audience_level.title()}

---

## 🪝 Opening Hook
{self.hook}

---

## 📝 Main Content
{self.body}

---

## 💡 Practical Explanation
{self.practical_explanation}

---

## 🎬 Suggested Visuals / Demo Concepts
{demo_lines}

---

## 📢 Call To Action
{self.cta}

---

**Source**: [{self.source_url}]({self.source_url})  
**Tags**: {tags_line}
"""
